create table charity_acceptance(organization_id bigint primary key references app_users(id),region varchar(120) not null,categories_json text not null,storage_conditions varchar(1000) not null,minimum_remaining_days integer not null,active boolean not null);
create table social_proposals(id bigint generated by default as identity primary key,version bigint not null default 0,decision_id bigint not null references pricing_decisions(id),product_id bigint not null references products(id),quantity integer not null,valid_until date not null,status varchar(20) not null,reason varchar(1000) not null,created_at timestamp not null,organization_id bigint references app_users(id),offer_id bigint references social_offers(id),approved_at timestamp,approved_by varchar(255),constraint uk_social_proposal_decision unique(decision_id),constraint ck_proposal_quantity check(quantity>0));
alter table pricing_decisions add column strategy varchar(20) not null default 'PRICE';
